#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin >> T;
    int dx[8]={-1,-1,-1,0,0,1,1,1};
    int dy[8]={-1,0,1,-1,1,-1,0,1};
    while (T--) {
        int m,n; cin >> m >> n;
        vector<string> grid(m);
        for (auto &s: grid) { cin >> s; for (auto &c: s) c = toupper(c); }
        int k; cin >> k;
        vector<string> results;
        while (k--) {
            string w; cin >> w;
            for (auto &c: w) c = toupper(c);
            int wl = w.size();
            int foundR=-1, foundC=-1;
            for (int i=0;i<m && foundR==-1;i++){
                for (int j=0;j<n && foundR==-1;j++){
                    if (grid[i][j] != w[0]) continue;
                    for (int d=0; d<8 && foundR==-1; d++){
                        int ci=i, cj=j; bool match=true;
                        for (int p=0;p<wl;p++){
                            if (ci<0||ci>=m||cj<0||cj>=n||grid[ci][cj]!=w[p]) { match=false; break; }
                            ci+=dx[d]; cj+=dy[d];
                        }
                        if (match) { foundR=i; foundC=j; }
                    }
                }
            }
            results.push_back(to_string(foundR+1) + " " + to_string(foundC+1));
        }
        for (auto &r: results) cout << r << "\n";
        if (T) cout << "\n";
    }
}

